  background: var(--bg);
  color: var(--text);
  font-family: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, system-ui, sans-serif;
  font-size: 16px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

img, svg { display: block; max-width: 100%; }

a { color: inherit; text-decoration: none; }
a:hover { color: var(--accent); }

:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 3px;
  border-radius: 4px;
}

.skip-link {
  position: absolute;
  left: -9999px;
  top: 0;
  background: var(--accent);
  color: #111;
  padding: .6rem 1rem;
  font-weight: 600;
  z-index: 1000;
}
.skip-link:focus { left: 1rem; top: 1rem; }

.visually-hidden {
  position: absolute !important;
  width: 1px; height: 1px;
  padding: 0; margin: -1px; overflow: hidden;
  clip: rect(0,0,0,0); white-space: nowrap; border: 0;
}

.container {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 0 24px;
}

h1, h2, h3, h4 {
  font-family: "Fraunces", "Playfair Display", Georgia, serif;
  font-weight: 500;
  letter-spacing: -0.01em;
  line-height: 1.15;
  margin: 0;
}
h1 { font-size: clamp(2.4rem, 5vw, 4rem); }
h2 { font-size: clamp(1.7rem, 3vw, 2.4rem); }
h3 { font-size: 1.15rem; line-height: 1.3; }
h4 { font-size: .95rem; letter-spacing: .04em; text-transform: uppercase; color: var(--text); }

p { margin: 0 0 1rem; }
p:last-child { margin-bottom: 0; }

.muted { color: var(--text-muted); }
.small { font-size: .85rem; }
.eyebrow {
  font-size: .78rem;
  letter-spacing: .18em;
  text-transform: uppercase;
  color: var(--accent);
  margin: 0 0 .6rem;
  font-weight: 500;
}
.eyebrow.small { font-size: .68rem; margin-bottom: .4rem; }
.accent { color: var(--accent); font-style: italic; }

/* ---------- Header ---------- */
.site-header {
  position: sticky; top: 0; z-index: 50;
  background: rgba(10, 11, 15, 0.78);
  backdrop-filter: saturate(160%) blur(14px);
  -webkit-backdrop-filter: saturate(160%) blur(14px);
  border-bottom: 1px solid var(--line);
}
.header-inner {
  display: flex; align-items: center; gap: 24px;
  height: 68px;
}
.brand {
  display: flex; align-items: center; gap: 10px;
  font-family: "Fraunces", Georgia, serif;
  font-size: 1.35rem;
  font-weight: 600;
  letter-spacing: .02em;
}
.brand:hover { color: var(--text); }
.brand-mark {
  color: var(--accent);
  font-size: 1.6rem;
  line-height: 1;
}

.primary-nav {
  margin-left: auto;
}
.primary-nav ul {
  display: flex; gap: 28px; list-style: none; margin: 0; padding: 0;
}
.primary-nav a {
  font-size: .92rem;
  color: var(--text);
  position: relative;
  padding: 4px 0;
}
.primary-nav a::after {
  content: ""; position: absolute; left: 0; right: 0; bottom: -2px;
  height: 1px; background: var(--accent); transform: scaleX(0);
  transform-origin: left; transition: transform .25s ease;
}
.primary-nav a:hover::after { transform: scaleX(1); }

.header-actions { display: flex; gap: 6px; }
.icon-btn {
  background: transparent; border: 1px solid transparent;
  color: var(--text); padding: 8px;
  border-radius: 999px; cursor: pointer;
  width: 40px; height: 40px;
  display: inline-flex; align-items: center; justify-content: center;
  position: relative;
  transition: background .2s, border-color .2s, color .2s;
}
.icon-btn:hover { background: var(--bg-elev-2); border-color: var(--line); }
.icon-btn svg { width: 20px; height: 20px; }
.cart-btn .cart-count {
  position: absolute; top: 2px; right: 2px;
  background: var(--accent); color: #111;
  font-size: .65rem; font-weight: 700;
  min-width: 18px; height: 18px; padding: 0 4px;
  border-radius: 999px;
  display: inline-flex; align-items: center; justify-content: center;
}

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex; align-items: center; justify-content: center;
  padding: 14px 22px;
  font-size: .92rem; font-weight: 500;
  border-radius: 999px;
  border: 1px solid transparent;
  cursor: pointer;
  transition: transform .15s ease, background .2s, color .2s, border-color .2s;
  text-align: center;
  letter-spacing: .01em;
}
.btn-sm { padding: 10px 16px; font-size: .85rem; }
.btn-primary {
  background: var(--accent); color: #15110a;
}
.btn-primary:hover { background: #d6b380; color: #15110a; transform: translateY(-1px); }
.btn-ghost {
  background: transparent; color: var(--text); border-color: var(--line-strong);
}
.btn-ghost:hover { border-color: var(--accent); color: var(--accent); }

.link-arrow {
  display: inline-flex; align-items: center; gap: 6px;
  color: var(--text); font-size: .9rem; font-weight: 500;
  border-bottom: 1px solid transparent;
  padding-bottom: 2px;
  transition: color .2s, border-color .2s, gap .2s;
}
.link-arrow:hover { color: var(--accent); border-color: var(--accent); gap: 10px; }
.link-arrow.small { font-size: .82rem; }

/* ---------- Hero ---------- */
.hero {
  position: relative;
  padding: 80px 0 100px;
  overflow: hidden;
  background:
    radial-gradient(900px 500px at 85% 20%, rgba(201,165,116,0.10), transparent 60%),
    radial-gradient(700px 600px at 10% 90%, rgba(138, 180, 255, 0.06), transparent 60%);
}
.hero-grid {
  display: grid; grid-template-columns: 1.1fr 1fr; gap: 60px; align-items: center;
}
.hero-copy h1 { margin-bottom: 1.2rem; }
.lede { font-size: 1.1rem; color: var(--text-muted); max-width: 48ch; margin-bottom: 2rem; }
.hero-cta { display: flex; gap: 12px; flex-wrap: wrap; margin-bottom: 3rem; }
.hero-stats {
  display: grid; grid-template-columns: repeat(3, 1fr);
  gap: 18px; margin: 0;
  padding-top: 1.6rem;
  border-top: 1px solid var(--line);
  max-width: 520px;
}
.hero-stats > div { }
.hero-stats dt { font-size: .72rem; letter-spacing: .14em; text-transform: uppercase; color: var(--text-dim); margin-bottom: 4px; }
.hero-stats dd { margin: 0; font-size: .92rem; color: var(--text); }

.hero-visual {
  position: relative; height: 520px;
}
.hero-card {
  position: absolute; border-radius: var(--radius);
  border: 1px solid var(--line);
  box-shadow: var(--shadow);
  overflow: hidden;
}
.hero-card-1 {
  inset: 0 30% 40% 0;
  background:
    linear-gradient(160deg, rgba(0,0,0,.2), rgba(0,0,0,.55)),
    linear-gradient(135deg, #2a2f3e, #14161e);
}
.hero-card-1::after {
  content: "Overcoat 01";
  position: absolute; left: 16px; bottom: 14px;
  font-family: "Fraunces", serif; font-size: 1rem; color: #d8dae3;
}
.hero-card-2 {
  inset: 22% 0 18% 38%;
  background:
    linear-gradient(160deg, rgba(0,0,0,.15), rgba(0,0,0,.5)),
    linear-gradient(135deg, #3a2e25, #1a140f);
}
.hero-card-2::after {
  content: "Knit 04";
  position: absolute; left: 16px; bottom: 14px;
  font-family: "Fraunces", serif; font-size: 1rem; color: #e7d8c2;
}
.hero-card-3 {
  inset: 60% 50% 0 6%;
  background:
    linear-gradient(160deg, rgba(0,0,0,.15), rgba(0,0,0,.55)),
    linear-gradient(135deg, #1d2a2c, #0f1617);
}
.hero-card-3::after {
  content: "Boot 02";
  position: absolute; left: 16px; bottom: 14px;
  font-family: "Fraunces", serif; font-size: 1rem; color: #cfd9d6;
}
.hero-glow {
  position: absolute; right: -80px; top: -80px; width: 280px; height: 280px;
  background: radial-gradient(circle, rgba(201,165,116,0.25), transparent 70%);
  filter: blur(20px);
  pointer-events: none;
}

/* ---------- Categories ---------- */
.categories {
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  background: var(--bg-elev);
}
.cat-list {
  display: flex; gap: 8px; flex-wrap: wrap;
  list-style: none; margin: 0; padding: 18px 0;
  justify-content: center;
}
.cat-list a {
  display: inline-block;
  padding: 8px 16px;
  border-radius: 999px;
  border: 1px solid var(--line);
  font-size: .85rem;
  color: var(--text-muted);
  background: var(--bg-elev-2);
  transition: color .2s, border-color .2s, background .2s;
}
.cat-list a:hover {
  color: var(--accent);
  border-color: var(--accent);
  background: var(--accent-soft);
}

/* ---------- Sections ---------- */
.section { padding: 88px 0; }
.section-head {
  display: flex; justify-content: space-between; align-items: end;
  gap: 24px; margin-bottom: 36px; flex-wrap: wrap;
}

/* ---------- Product grid ---------- */
.product-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.product {
  background: var(--bg-elev);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
  transition: transform .3s ease, border-color .3s ease, box-shadow .3s ease;
  display: flex; flex-direction: column;
}
.product:hover {
  transform: translateY(-4px);
  border-color: var(--line-strong);
  box-shadow: var(--shadow);
}
.product-art {
  position: relative;
  aspect-ratio: 4 / 5;
  background: linear-gradient(135deg, #1d2230, #0f121a);
  overflow: hidden;
}
.product-art::before {
  content: ""; position: absolute; inset: 0;
  background: radial-gradient(120% 80% at 50% 100%, rgba(255,255,255,.05), transparent 60%);
}
.product-art .swatch {
  position: absolute; inset: 12% 18%;
  border-radius: 10px;
  box-shadow: inset 0 0 80px rgba(0,0,0,.4), 0 20px 40px rgba(0,0,0,.35);
}
.product-tag {
  position: absolute; top: 12px; left: 12px;
  background: rgba(0,0,0,.55);
  border: 1px solid var(--line-strong);
  color: var(--text);
  font-size: .68rem; letter-spacing: .12em; text-transform: uppercase;
  padding: 4px 10px; border-radius: 999px;
  backdrop-filter: blur(6px);
}
.product-tag.new { color: var(--accent); border-color: rgba(201,165,116,.5); }
.product-tag.sale { color: var(--accent-hot); border-color: rgba(224,122,95,.5); }

.wishlist {
  position: absolute; top: 10px; right: 10px;
  background: rgba(10,11,15,.6);
  border: 1px solid var(--line);
  width: 36px; height: 36px; border-radius: 999px;
  color: var(--text);
  display: inline-flex; align-items: center; justify-content: center;
  cursor: pointer;
  transition: color .2s, background .2s, transform .15s;
}
.wishlist:hover { color: var(--accent-hot); background: var(--bg-elev-2); transform: scale(1.05); }
.wishlist[aria-pressed="true"] { color: var(--accent-hot); }
.wishlist svg { width: 18px; height: 18px; }

.product-body { padding: 18px; display: flex; flex-direction: column; gap: 10px; flex: 1; }
.product-name { font-family: "Fraunces", serif; font-size: 1.05rem; }
.product-meta { display: flex; justify-content: space-between; align-items: center; }
.product-price { display: flex; gap: 8px; align-items: baseline; }
.price { font-weight: 600; color: var(--text); }
.price-was { color: var(--text-dim); font-size: .85rem; }
.product-rating { color: var(--accent); font-size: .8rem; }
.product-rating .count { color: var(--text-dim); margin-left: 4px; }

.add-btn {
  margin-top: auto;
  background: transparent;
  border: 1px solid var(--line-strong);
  color: var(--text);
  padding: 10px 14px; border-radius: 999px;
  font-size: .85rem; cursor: pointer;
  transition: background .2s, color .2s, border-color .2s;
}
.add-btn:hover { background: var(--accent); color: #15110a; border-color: var(--accent); }

/* ---------- Deals ---------- */
.section-deals {
  background: linear-gradient(180deg, var(--bg) 0%, #0d0f17 100%);
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}
.countdown {
  font-family: "JetBrains Mono", "SF Mono", Menlo, monospace;
  color: var(--text-muted);
  font-size: .9rem;
  margin: 0;
}
.countdown time { color: var(--accent); font-weight: 600; }

.deals-grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr 1fr;
  grid-template-rows: auto auto;
  gap: 20px;
}
.deal {
  background: var(--bg-elev);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex; flex-direction: column;
  transition: border-color .25s, transform .25s;
}
.deal:hover { border-color: var(--line-strong); transform: translateY(-3px); }
.deal-feature {
  grid-row: span 2;
  flex-direction: column;
}
.deal-art {
  position: relative;
  aspect-ratio: 4 / 3;
  background: linear-gradient(135deg, #2a2218, #14110b);
}
.deal-feature .deal-art { aspect-ratio: 16 / 11; }
.deal-art-2 { background: linear-gradient(135deg, #1f2a2e, #11181b); }
.deal-art-3 { background: linear-gradient(135deg, #2a1f24, #161013); }
.deal-art-4 { background: linear-gradient(135deg, #20251f, #11140f); }
.deal-art::after {
  content: ""; position: absolute; inset: 14% 22%;
  border-radius: 8px;
  background: rgba(255,255,255,.03);
  border: 1px solid rgba(255,255,255,.04);
}

.badge {
  position: absolute; top: 14px; left: 14px;
  background: var(--accent); color: #15110a;
  font-size: .72rem; font-weight: 700;
  letter-spacing: .06em;
  padding: 5px 10px; border-radius: 999px;
  z-index: 1;
}
.badge-hot { background: var(--accent-hot); color: #fff; }

.deal-body { padding: 22px; display: flex; flex-direction: column; gap: 8px; flex: 1; }
.deal-feature .deal-body { padding: 28px; gap: 12px; }
.deal-feature h3 { font-size: 1.6rem; }
.price-row { display: flex; gap: 10px; align-items: baseline; margin: 6px 0 14px; }
.price-row .price { font-size: 1.25rem; color: var(--accent); }

/* ---------- Editorial ---------- */
.editorial-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  grid-template-rows: auto auto;
  gap: 24px;
}
.story {
  background: var(--bg-elev);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex; flex-direction: column;
  transition: border-color .25s, transform .25s;
}
.story:hover { border-color: var(--line-strong); transform: translateY(-3px); }
.story-lead { grid-row: span 2; }
.story-art {
  aspect-ratio: 16 / 10;
  background: linear-gradient(135deg, #1c2230, #0c0f17);
}
.story-lead .story-art { aspect-ratio: 4 / 3; }
.story-art-1 { background: linear-gradient(135deg, #2b1e15, #150e08), radial-gradient(circle at 30% 30%, rgba(255,255,255,.06), transparent 60%); }
.story-art-2 { background: linear-gradient(135deg, #1a2030, #0d1018); }
.story-art-3 { background: linear-gradient(135deg, #2a242a, #14111a); }
.story-art-4 { background: linear-gradient(135deg, #1e2722, #0e1310); }
.story-body { padding: 20px; display: flex; flex-direction: column; gap: 8px; flex: 1; }
.story-lead .story-body { padding: 28px; }
.story-lead h3 { font-size: 1.5rem; }
.story-body .link-arrow { margin-top: auto; padding-top: 8px; }

/* ---------- Newsletter ---------- */
.newsletter {
  background:
    radial-gradient(700px 300px at 80% 50%, rgba(201,165,116,0.12), transparent 70%),
    var(--bg-elev);
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  padding: 80px 0;
}
.news-inner {
  display: grid; grid-template-columns: 1fr 1fr; gap: 60px; align-items: center;
}
.news-form {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 10px;
  position: relative;
}
.news-form input {
  background: var(--bg);
  border: 1px solid var(--line-strong);
  color: var(--text);
  padding: 14px 18px;
  border-radius: 999px;
  font-size: .95rem;
  font-family: inherit;
  transition: border-color .2s;
}
.news-form input::placeholder { color: var(--text-dim); }
.news-form input:focus { outline: none; border-color: var(--accent); }
.news-msg {
  grid-column: 1 / -1;
  margin: 6px 4px 0;
  font-size: .85rem;
  min-height: 1.2em;
  color: var(--text-muted);
}
.news-msg.success { color: #8fd3a4; }
.news-msg.error { color: #e8a59a; }

/* ---------- Footer ---------- */
.site-footer {
  background: #08090d;
  padding: 60px 0 28px;
  border-top: 1px solid var(--line);
}
.footer-grid {
  display: grid; grid-template-columns: 1.4fr repeat(3, 1fr); gap: 40px;
  padding-bottom: 40px;
  border-bottom: 1px solid var(--line);
}
.brand-footer { margin-bottom: 14px; }
.site-footer h4 { margin: 0 0 16px; }
.site-footer ul { list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 10px; }
.site-footer a { color: var(--text-muted); font-size: .9rem; }
.site-footer a:hover { color: var(--accent); }
.footer-bottom {
  display: flex; justify-content: space-between; align-items: center;
  padding-top: 24px;
  flex-wrap: wrap; gap: 12px;
}
.legal-links {
  list-style: none; padding: 0; margin: 0;
  display: flex; gap: 20px;
}

/* ---------- Toast ---------- */
.toast {
  position: fixed; bottom: 24px; left: 50%;
  transform: translateX(-50%) translateY(20px);
  background: var(--bg-elev-2);
  color: var(--text);
  border: 1px solid var(--line-strong);
  padding: 12px 20px;
  border-radius: 999px;
  font-size: .9rem;
  box-shadow: var(--shadow);
  opacity: 0;
  pointer-events: none;
  transition: opacity .25s ease, transform .25s ease;
  z-index: 100;
}
.toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }

/* ---------- Responsive ---------- */
@media (max-width: 980px) {
  .hero-grid { grid-template-columns: 1fr; gap: 40px; }
  .hero-visual { height: 380px; }
  .product-grid { grid-template-columns: repeat(2, 1fr); }
  .deals-grid { grid-template-columns: 1fr 1fr; }
  .deal-feature { grid-row: auto; grid-column: 1 / -1; }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .story-lead { grid-row: auto; grid-column: 1 / -1; }
  .news-inner { grid-template-columns: 1fr; gap: 30px; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .section { padding: 64px 0; }
}
@media (max-width: 640px) {
  .primary-nav { display: none; }
  h1 { font-size: 2.2rem; }
  .hero { padding: 56px 0 72px; }
  .hero-stats { grid-template-columns: 1fr; gap: 12px; }
  .product-grid { grid-template-columns: 1fr 1fr; gap: 14px; }
  .product-body { padding: 14px; }
  .deals-grid { grid-template-columns: 1fr; }
  .editorial-grid { grid-template-columns: 1fr; }
  .news-form { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; gap: 28px; }
  .footer-bottom { flex-direction: column; align-items: flex-start; }
  .section-head { align-items: flex-start; flex-direction: column; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

