+  margin: 6px 4px 0;
+  font-size: .85rem;
+  min-height: 1.2em;
+  color: var(--text-muted);
+}
+.news-msg.success { color: #8fd3a4; }
+.news-msg.error { color: #e8a59a; }
+
+/* ---------- Footer ---------- */
+.site-footer {
+  background: #08090d;
+  padding: 60px 0 28px;
+  border-top: 1px solid var(--line);
+}
+.footer-grid {
+  display: grid; grid-template-columns: 1.4fr repeat(3, 1fr); gap: 40px;
+  padding-bottom: 40px;
+  border-bottom: 1px solid var(--line);
+}
+.brand-footer { margin-bottom: 14px; }
+.site-footer h4 { margin: 0 0 16px; }
+.site-footer ul { list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 10px; }
+.site-footer a { color: var(--text-muted); font-size: .9rem; }
+.site-footer a:hover { color: var(--accent); }
+.footer-bottom {
+  display: flex; justify-content: space-between; align-items: center;
+  padding-top: 24px;
+  flex-wrap: wrap; gap: 12px;
+}
+.legal-links {
+  list-style: none; padding: 0; margin: 0;
+  display: flex; gap: 20px;
+}
+
+/* ---------- Toast ---------- */
+.toast {
+  position: fixed; bottom: 24px; left: 50%;
+  transform: translateX(-50%) translateY(20px);
+  background: var(--bg-elev-2);
+  color: var(--text);
+  border: 1px solid var(--line-strong);
+  padding: 12px 20px;
+  border-radius: 999px;
+  font-size: .9rem;
+  box-shadow: var(--shadow);
+  opacity: 0;
+  pointer-events: none;
+  transition: opacity .25s ease, transform .25s ease;
+  z-index: 100;
+}
+.toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }
+
+/* ---------- Responsive ---------- */
+@media (max-width: 980px) {
+  .hero-grid { grid-template-columns: 1fr; gap: 40px; }
+  .hero-visual { height: 380px; }
+  .product-grid { grid-template-columns: repeat(2, 1fr); }
+  .deals-grid { grid-template-columns: 1fr 1fr; }
+  .deal-feature { grid-row: auto; grid-column: 1 / -1; }
+  .editorial-grid { grid-template-columns: 1fr 1fr; }
+  .story-lead { grid-row: auto; grid-column: 1 / -1; }
+  .news-inner { grid-template-columns: 1fr; gap: 30px; }
+  .footer-grid { grid-template-columns: 1fr 1fr; }
+  .section { padding: 64px 0; }
+}
+@media (max-width: 640px) {
+  .primary-nav { display: none; }
+  h1 { font-size: 2.2rem; }
+  .hero { padding: 56px 0 72px; }
+  .hero-stats { grid-template-columns: 1fr; gap: 12px; }
+  .product-grid { grid-template-columns: 1fr 1fr; gap: 14px; }
+  .product-body { padding: 14px; }
+  .deals-grid { grid-template-columns: 1fr; }
+  .editorial-grid { grid-template-columns: 1fr; }
+  .news-form { grid-template-columns: 1fr; }
+  .footer-grid { grid-template-columns: 1fr; gap: 28px; }
+  .footer-bottom { flex-direction: column; align-items: flex-start; }
+  .section-head { align-items: flex-start; flex-direction: column; }
+}
+
+@media (prefers-reduced-motion: reduce) {
+  *, *::before, *::after {
+    animation-duration: 0.01ms !important;
+    transition-duration: 0.01ms !important;
+    scroll-behavior: auto !important;
+  }
+}
+
')

